#define main original_engine_main
#include "engine_test.cpp"
#undef main
#include <set>
int main(){Host h;auto&p=*h.p;const int slots[]={4,5,0,1,8,9},notes[]={24,26,28,29,31,33},drums[]={72,74,76,77,79,81,83,84};std::set<int>used;for(int i=0;i<6;++i){assert(p.getInt(p.performanceNoteKey(slots[i]))==notes[i]);assert(used.insert(notes[i]).second);assert(notes[i]-notes[0]<12);}for(int i=0;i<8;++i){assert(p.getInt(kPadNote0+i*9)==drums[i]);assert(used.insert(drums[i]).second);}auto dice=p.diceRolls.load();auto kit=p.getInt(kXKit);p.set(kCommandPads,1);p.set(kCommandLearn,3);for(int i=0;i<6;++i){p.stopPerformance();h.note(notes[i]);assert(p.selectedPerformance()==slots[i]);assert(p.performanceQueued.load()==slots[i]-4||p.queuedRoll.load()==slots[i]||p.performanceActive.load()==slots[i]);}assert(p.diceRolls.load()==dice&&p.getInt(kXKit)==kit&&!p.getBool(kPreview));for(int n:{25,27,35}){p.stopPerformance();h.note(n);assert(p.performanceQueued.load()<0&&p.queuedRoll.load()<0&&!p.getBool(kPreview));}for(int n:drums){auto count=p.fired.load();h.note(n);assert(p.fired.load()>count);}std::cout<<"PASS six C Major A triggers, eight C-bank drum notes, no pad Dice/preset/loop commands\n";}
